Here is a Python function that implements the dynamic programming approach to find the Longest Common Subsequence (LCS) of two input strings:

```python
def longest_common_subsequence(text1: str, text2: str) -> str:
    m, n = len(text1), len(text2)

    # Create a 2D DP table to store lengths of LCS
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if text1[i - 1] == text2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # Reconstruct the LCS string from the DP table
    lcs = []
    i, j = m, n
    while i > 0 and j > 0:
        if text1[i - 1] == text2[j - 1]:
            lcs.append(text1[i - 1])
            i -= 1
            j -= 1
        elif dp[i - 1][j] >= dp[i][j - 1]:
            i -= 1
        else:
            j -= 1

    # Reverse the reconstructed sequence to get the correct order
    return "".join(reversed(lcs))

# Example usage:
# string1 = "abcde"
# string2 = "ace"
# print(longest_common_subsequence(string1, string2)) # Output: "ace"
```

